#!/usr/bin/env python3
"""paper_paths.py - shared path/config helpers for the paper-processing pipeline.

A "paper_id" looks like "2012p1a" (year + paper code). Every pipeline script
(render_pages.py, segment_pages.py, crop_all_figures.py, build_database.py,
render_markdown.py) takes a paper_id and derives all its paths from here, so
adding a new year only means creating work/questions_data_<paper_id>.py plus
answer_id/source PDF entries below.
"""
import os

ROOT = os.path.dirname(os.path.abspath(__file__))
PAPER_ROOT = os.path.dirname(ROOT)

# paper_id -> (question paper PDF relative to PAPER_ROOT, answer PDF, num_questions)
PAPERS = {
    "2012p1a": {
        "mc_pdf": "Year/MC/2012p1a.pdf",
        "answer_pdf": "Year/Answer/2012ans.pdf",
        "answer_id": "2012ans",
        "num_questions": 36,
        "year": 2012,
    },
    "2013p1a": {
        "mc_pdf": "Year/MC/2013p1a.pdf",
        "answer_pdf": "Year/Answer/2013ans.pdf",
        "answer_id": "2013ans",
        "num_questions": 36,
        "year": 2013,
    },
}


def paper_config(paper_id):
    if paper_id not in PAPERS:
        raise KeyError(
            f"Unknown paper_id {paper_id!r}. Add it to PAPERS in work/paper_paths.py "
            f"(known: {sorted(PAPERS)})"
        )
    return PAPERS[paper_id]


def pages_dir(paper_id):
    return os.path.join(ROOT, "pages", paper_id)


def ans_pages_dir(paper_id):
    return os.path.join(ROOT, "pages", paper_config(paper_id)["answer_id"])


def ocr_dir(paper_id):
    return os.path.join(ROOT, "ocr", paper_id)


def ans_ocr_dir(paper_id):
    return os.path.join(ROOT, "ocr", paper_config(paper_id)["answer_id"])


def figures_dir(paper_id):
    return os.path.join(ROOT, "figures", paper_id)


def stems_dir(paper_id):
    return os.path.join(figures_dir(paper_id), "stems")


def opts_dir(paper_id):
    return os.path.join(figures_dir(paper_id), "opts")


def manifest_path(paper_id):
    return os.path.join(ROOT, "figures", paper_id, "segments.json")


def questions_data_module(paper_id):
    """Module name for the hand-authored transcription file, e.g.
    'questions_data_2013p1a' -> work/questions_data_2013p1a.py.
    2012p1a is special-cased to the original 'questions_data' module name
    for backward compatibility."""
    if paper_id == "2012p1a":
        return "questions_data"
    return f"questions_data_{paper_id}"

