def trim_horizontal(image):
    """Find left/right content bounds and crop to keep just the content + small margin."""
    gray = image.convert("L")
    w, h = gray.size
    px = gray.load()
    min_x = w
    max_x = -1
    # Sample every 2 rows for speed
    for y in range(0, h, 2):
        for x in range(w):
            if px[x, y] < WHITE_THRESHOLD:
                if x < min_x:
                    min_x = x
                # Track max from right
                if x > max_x:
                    max_x = x
                # Don't break — we need to scan all of x for max
        # Continue scanning for max even after finding min
    if max_x < 0:
        return image  # All white, return original
    left = max(0, min_x - KEEP_MARGIN)
    right = min(w, max_x + KEEP_MARGIN + 1)
    return image.crop((left, 0, right, h))


def trim_vertical(image, min_keep=20):
    """Trim top/bottom white space so the question sits flush.

    `min_keep` is the minimum number of pixels to keep at top/bottom to avoid
    chopping off table/figure edges that bleed into the rows we sampled.
    """
    gray = image.convert("L")
    w, h = gray.size
    px = gray.load()
    # First non-white row from top
    top = 0
    for y in range(h):
        if any(px[x, y] < WHITE_THRESHOLD for x in range(0, w, 4)):
            top = y
            break
    else:
        return image  # all white
    # Last non-white row from bottom
    bottom = h - 1
    for y in range(h - 1, -1, -1):
        if any(px[x, y] < WHITE_THRESHOLD for x in range(0, w, 4)):
            bottom = y
            break
    top = max(0, top - KEEP_MARGIN)
    bottom = min(h, bottom + KEEP_MARGIN + 1)
    if bottom <= top + min_keep:
        return image  # too thin to trim safely
    return image.crop((0, top, w, bottom))

