def ocr_region(image: Image.Image, top: int, bottom: int) -> str:
    """Run tesseract on the [top, bottom] row range of `image` and return
    the recognised text. Tries both PSM 6 and PSM 11 and returns whichever
    has more content.
    """
    if top < 0:
        top = 0
    if bottom > image.size[1]:
        bottom = image.size[1]
    if bottom - top < 5:
        return ""
    crop = image.crop((0, top, image.size[0], bottom))
    # Upscale 2x so tesseract has more pixels to work with
    crop = crop.resize((crop.size[0] * 2, crop.size[1] * 2))
    import tempfile
    with tempfile.NamedTemporaryFile(suffix=".png", delete=False) as tf:
        crop.save(tf.name)
        path = tf.name
    best_text = ""
    try:
        for psm in ("6", "11"):
            r = subprocess.run(
                ["tesseract", path, "stdout", "--psm", psm],
                capture_output=True, text=True, timeout=20,
            )
            if len(r.stdout) > len(best_text):
                best_text = r.stdout
        return best_text
    finally:
