def verify_paper(paper_id: str) -> list[dict]:
    """Return list of per-question verification results for `paper_id`.

    We OCR the bottom region of each crop to look for footer / next-question
    bleed, and we use the EXISTING OCR cache (which built segments) to
    locate the question-number marker in the crop's top region (since the
    cache already knows where every "N." marker is on every page).
    """
    cfg = paper_config(paper_id)
    num_q = cfg["num_questions"]
    crop_dir = Path(PAPER_ROOT) / "crop" / paper_id
    if not crop_dir.is_dir():
        return []
    seg_path = Path(PAPER_ROOT) / "work" / "figures" / paper_id / "segments_smart.json"
    if not seg_path.exists():
        return []
    with open(seg_path) as fh:
        segments = json.load(fh)
    # Load OCR cache
    cache_path = Path(PAPER_ROOT) / "work" / "ocr_cache" / f"{paper_id}.json"
    ocr_cache = {}
    if cache_path.exists():
        try:
            with open(cache_path) as fh:
                raw = json.load(fh)
            ocr_cache = {int(k): v for k, v in raw.items()}
        except Exception:
            pass

    results = []
    for qnum in range(1, num_q + 1):
        path = crop_dir / f"q{qnum:02d}.png"
        if not path.exists():
            results.append({
                "paper": paper_id,
                "qnum": qnum,
                "ok": False,
                "error": "missing",
            })
            continue
        try:
            img = Image.open(path)
        except Exception as e:
            results.append({
                "paper": paper_id,
                "qnum": qnum,
                "ok": False,
                "error": f"open failed: {e}",
            })
            continue
        w, h = img.size
        seg = segments.get(str(qnum), {})
        page = seg.get("page")
        y0 = seg.get("y0")

        # OCR bottom region for footer / next-question bleed
        bottom_text = ocr_region(img, max(0, h - BOTTOM_BAND), h)

        issues = []
        if has_footer_bleed(bottom_text):
            footer_match = ""
            for pat in FOOTER_PATTERNS:
                m = re.search(pat, bottom_text, re.IGNORECASE)
                if m:
                    footer_match = m.group(0)
                    break
            issues.append(f"footer_bleed: {footer_match!r}")
        is_bleed, marker = next_question_bleed(bottom_text, qnum)
        if is_bleed:
            issues.append(f"next_q_bleed: {marker!r}")

        # Question-marker presence: use the OCR cache to verify
        # that the question-number marker is within the crop's vertical
        # range. We expect: crop_y0 <= marker_top + small_slack AND
        # marker_top <= crop_y1 (or close).
        if page is not None and page in ocr_cache:
            # Find the OCR-detected "qnum." word on the same page whose
            # top is closest to (or just above) the segment y0.
            best_word = None
            for wobj in ocr_cache[page]:
                txt = wobj["text"]
                if re.match(rf"^\*?#{qnum}[.,;:]|^0{qnum}[.,;:]|^{qnum}[.,;:]", txt):
                    # This is a candidate marker for our question
                    if best_word is None or abs(wobj["top"] - y0) < abs(best_word["top"] - y0):
                        best_word = wobj
            if best_word is not None:
                # The marker must be within the crop with some slack
                # crop_y0 = y0 - PAD_TOP, so we allow marker_top to be
                # in [y0 - 20, y0 + 30]
                if not (y0 - 20 <= best_word["top"] <= y0 + 30):
                    issues.append(
                        f"marker_off: y0={y0}, marker_top={best_word['top']}, "
                        f"text={best_word['text']!r}"
                    )
            else:
                issues.append("no_marker_in_ocr")
        else:
            issues.append("no_ocr_cache")

        results.append({
            "paper": paper_id,
            "qnum": qnum,
            "ok": not issues,
            "issues": issues,
            "size": [w, h],
        })
    return results

