def column_of(x_left, page_width):
    """Return 'left' or 'right' depending on which half of the page x_left
    falls in. For wide pages (double-page spreads), this distinguishes the
    two columns; for narrow pages, always returns 'left'.

    If x_left is None (no OCR data), assume 'left' as a safe default.
    """
    if page_width <= WIDE_PAGE_THRESHOLD:
        return "left"
    if x_left is None:
        return "left"
    return "left" if x_left < page_width / 2 else "right"


def find_real_marker_top(page_words, qnum):
    """Find the OCR-detected top coordinate of a question's marker on a page.

    Uses strict matching first ("N.", "*N."), then tries OCR slips like
    "L." (for "1.") and loose-match (bare "N" + uppercase letter next).
    Returns the top of the marker, or None if not found.
    """
    for i_w, w in enumerate(page_words):
        t = w["text"]
        # Strict: "*N." or "#N." or "N." or "N,"
        m = (re.fullmatch(r"\*?#?(\d{1,2})[.,;:/\u2014\u2013-]", t)
             or None)
        if m:
            n = int(m.group(1))
            if n == qnum and w["left"] < 1500:
                return w["top"]
            continue
        # OCR slip: "ll." should be "11."
        if t == "ll." and qnum == 11 and w["left"] < 1500:
            return w["top"]
        # OCR slip: "L." / "l." is "1."
        if t in ("L.", "l.", "l,", "L,") and qnum == 1 and w["left"] < 500:
            return w["top"]
        # Bare digit followed by an uppercase alpha word
        if re.fullmatch(r"\d{1,2}", t):
            try:
                nv = int(t)
            except ValueError:
                continue
            if nv != qnum:
                continue
            if i_w + 1 < len(page_words):
                nxt_w = page_words[i_w + 1]
                nxt = nxt_w["text"]
                if (nxt and len(nxt) >= 1 and nxt[0].isalpha()
                        and nxt[0].isupper()
                        and w["left"] < 400
                        and nxt_w["left"] > w["left"] + 30):
                    return w["top"]
    return None


