def h_trim(img: Image.Image) -> Image.Image:
    """Trim horizontal whitespace using ink-density projection.

    The dse watermark/binding leaves very light ink (<5 ink px per col),
    so we only trim col whose ink density is above MIN_INK_COL.
    """
    px = img.convert("L").load()
    W, H = img.size
    TH = 200
    MIN_INK_COL = 5
    # For each col, count ink pixels (sample every 2 rows for speed)
    cols_ink = [0] * W
    for x in range(W):
        for y in range(0, H, 2):
            if px[x, y] < TH:
                cols_ink[x] += 1
    nz = [i for i, v in enumerate(cols_ink) if v >= MIN_INK_COL]
    if not nz:
        return img
    c0, c1 = nz[0], nz[-1]
    # Add padding
    c0 = max(0, c0 - 10)
    c1 = min(W - 1, c1 + 10)
    return img.crop((c0, 0, c1 + 1, H))


def trim_vertical(img: Image.Image) -> Image.Image:
    """Trim vertical whitespace."""
    px = img.convert("L").load()
    W, H = img.size
    TH = 200
    rows_ink = [0] * H
    for y in range(H):
        for x in range(0, W, 4):
            if px[x, y] < TH:
                rows_ink[y] += 1
    nz = [i for i, v in enumerate(rows_ink) if v >= 3]
    if not nz:
        return img
    r0, r1 = nz[0], nz[-1]
    r0 = max(0, r0 - 5)
    r1 = min(H - 1, r1 + 5)
    return img.crop((0, r0, W, r1 + 1))

