"""Improved verifier using OCR words + positions."""
import re, subprocess
from pathlib import Path
from PIL import Image

PAPER = "2012p1a"
CROP = Path(f"/Users/sinchunyeung/Documents-local/Materials/Phy/DSE/scripts/processed/crop/{PAPER}")

def ocr_tsv(img_path):
    out = subprocess.run(
        ["tesseract", str(img_path), "-", "--psm", "11", "tsv"],
        capture_output=True, text=True
    )
    rows = []
    lines = out.stdout.splitlines()
    for ln in lines[1:]:
        parts = ln.split("\t")
        if len(parts) < 12:
            continue
        try:
            level = int(parts[0])
            txt = parts[11].strip()
            top = int(parts[7])
            left = int(parts[6])
            w = int(parts[8])
            h = int(parts[9])
        except ValueError:
            continue
        if level == 5 and txt:
            rows.append({"text": txt, "top": top, "left": left, "w": w, "h": h})
    return rows

def find_options(words, qnum_y_start):
    """Find the option markers (A, B, C, D) in OCR words.
    An option is a single uppercase letter followed by a period or
    parenthesis, with a sensible height (similar to question body)."""
    opts = {}
    for w in words:
        t = w["text"]
        if re.fullmatch(r"[A-D][\.\)\,;:]", t) or re.fullmatch(r"[A-D]\s*[\.\)]", t):
            opts.setdefault(t[0], w["top"])
        # OCR misreads: "A " followed by content
    return opts

def has_marker(words, qnum):
    for w in words:
        if re.fullmatch(rf"\**\s*{qnum}\s*[\.\-,;:]", w["text"]):
            return True
        if w["text"] == f"{qnum}":
            return True
    return False

issues = []
ok = 0
for i in range(1, 37):
    p = CROP / f"q{i:02d}.png"
    if not p.exists():
        issues.append(f"Q{i}: MISSING file")
        continue
    words = ocr_tsv(p)
    has_qn = has_marker(words, i)
    # Options detection: look for 'A.', 'B.', 'C.', 'D.' anywhere in words
    opts = set()
    for w in words:
        t = w["text"]
        if len(t) == 2 and t[0] in "ABCD" and t[1] in ".,),:":
            opts.add(t[0])
        if len(t) >= 2 and t[0] in "ABCD" and t[1] == " " and len(t) <= 3:
            opts.add(t[0])
    missing = sorted(set("ABCD") - opts)
    # Check next marker
    next_in = has_marker(words, i + 1) if i < 36 else False
    notes = []
    if not has_qn:
        notes.append("no-marker")
    if missing:
        notes.append(f"missing {missing}")
    if next_in:
        notes.append(f"contains Q{i+1}")
    if notes:
        issues.append(f"Q{i}: {', '.join(notes)}")
    else:
        ok += 1

print(f"\n=== {ok} OK, {len(issues)} with issues ===")
for it in issues:
    print(" ", it)
